import { apiPath } from '../lib/apiUrl';

const API = apiPath('/api/cozinha-portal');
const TOKEN_KEY = 'cozinha_access_token';

export const getCozinhaToken = () => localStorage.getItem(TOKEN_KEY);
export const setCozinhaToken = (token) => localStorage.setItem(TOKEN_KEY, token);
export const clearCozinhaToken = () => localStorage.removeItem(TOKEN_KEY);

async function cozinhaFetch(path, options = {}) {
  const token = getCozinhaToken();
  if (!token) throw new Error('Token de cozinha não encontrado. Use o link recebido do restaurante.');

  const res = await fetch(`${API}${path}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      'x-cozinha-token': token,
      ...options.headers,
    },
  });

  const contentType = res.headers.get('content-type') ?? '';
  const isJson = contentType.includes('application/json');

  if (!res.ok) {
    const err = isJson ? await res.json().catch(() => ({})) : {};
    throw new Error(err?.message ?? `HTTP ${res.status}`);
  }

  return isJson ? res.json() : {};
}

export const getCozinhaMe = () => cozinhaFetch('/me');
// Troca o token atual (tipicamente o que veio de um link/QR compartilhado)
// por um novo, invalidando o antigo — ver F2 da auditoria de segurança.
export const resgatarToken = () => cozinhaFetch('/resgatar-token', { method: 'POST' });
export const getCozinhaPedidos = () => cozinhaFetch('/pedidos');
export const atualizarStatusCozinhaPortal = (pedidoId, status) =>
  cozinhaFetch(`/pedidos/${pedidoId}/status`, {
    method: 'PATCH',
    body: JSON.stringify({ status }),
  });

// KDS por setor (módulo Salão) — mesmo token de cozinha, endpoint diferente
const API_KDS = apiPath('/api/kds-portal');
async function kdsFetch(path, options = {}) {
  const token = getCozinhaToken();
  if (!token) throw new Error('Token de cozinha não encontrado. Use o link recebido do restaurante.');

  const res = await fetch(`${API_KDS}${path}`, {
    ...options,
    headers: { 'Content-Type': 'application/json', 'x-cozinha-token': token, ...options.headers },
  });
  const contentType = res.headers.get('content-type') ?? '';
  const isJson = contentType.includes('application/json');
  if (!res.ok) {
    const err = isJson ? await res.json().catch(() => ({})) : {};
    throw new Error(err?.message ?? `HTTP ${res.status}`);
  }
  return isJson ? res.json() : {};
}

export const getKdsImpressoras = () => kdsFetch('/impressoras');
export const getKdsItens = (impressoraId) => kdsFetch(`/itens?impressora_id=${impressoraId}`);
export const marcarItemPronto = (itemId) => kdsFetch(`/itens/${itemId}/pronto`, { method: 'PATCH' });
export const reimprimirItem = (itemId) =>
  kdsFetch(`/itens/${itemId}/reimprimir`, { method: 'POST' });
export const iniciarPreparoItem = (itemId) =>
  kdsFetch(`/itens/${itemId}/iniciar-preparo`, { method: 'PATCH' });
export const voltarStatusItem = (itemId) =>
  kdsFetch(`/itens/${itemId}/voltar`, { method: 'PATCH' });

