1	import React, { useState, useEffect, useCallback, useRef } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { listarImpressoras, getKdsItensRestaurante, marcarItemProntoRestaurante, reimprimirItemRestaurante, iniciarPreparoItemRestaurante, voltarStatusItemRestaurante, cancelarItemRestaurante, moverItemRestaurante, getMinhaEmpresa, getSalaoComandaDetalhe, editarItemComandaSalao } from '../../services/restauranteService';
4	import { printTicketSetor } from '../../utils/printComanda';
5	import { useNotificacaoSonora } from '../../hooks/useNotificacaoSonora';
6	import { useNowTick } from '../../hooks/useNowTick';
7	import Icon from '../../components/AppIcon';
8	import SalaoItemCard from '../../components/restaurante/SalaoItemCard';
9	
10	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
11	
12	// Clique no card (só itens de Salão, com numero_comanda) abre essa comanda completa —
13	// mesmo endpoint que o PDV do Salão usa, só leitura aqui (sem ações de pagamento).
14	const ComandaModal = ({ orderId, onFechar }) => {
15	  const [comanda, setComanda] = useState(null);
16	  const [erro, setErro] = useState(null);
17	
18	  useEffect(() => {
19	    getSalaoComandaDetalhe(orderId).then(setComanda).catch((e) => setErro(e.message));
20	  }, [orderId]);
21	
22	  return (
23	    <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4" onClick={onFechar}>
24	      <div className="bg-[#1A1A1A] border border-[#2A2A2A] rounded-2xl w-full max-w-md max-h-[85vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
25	        <div className="flex items-center justify-between px-4 py-3 border-b border-[#2A2A2A] sticky top-0 bg-[#1A1A1A]">
26	          <h2 className="text-sm font-black text-white">
27	            Comanda {comanda?.numero_comanda ? `#${comanda.numero_comanda}` : ''}
28	          </h2>
29	          <button onClick={onFechar} className="p-1 text-[#71717A] hover:text-white"><Icon name="X" size={18} /></button>
30	        </div>
31	        <div className="p-4">
32	          {erro && <p className="text-sm text-red-400">{erro}</p>}
33	          {!comanda && !erro && <p className="text-sm text-[#71717A]">Carregando...</p>}
34	          {comanda && (
35	            <>
36	              <p className="text-xs text-[#71717A] mb-3">
37	                {comanda.mesas ? `Mesa ${comanda.mesas.numero}${comanda.mesas.nome ? ' - ' + comanda.mesas.nome : ''}` : comanda.cliente_mesa_nome}
38	                {comanda.garcons?.nome && ` • Garçom: ${comanda.garcons.nome}`}
39	                {comanda.aberto_por_nome && ` • Aberto por: ${comanda.aberto_por_nome}`}
40	              </p>
41	              <div className="space-y-2 mb-3">
42	                {(comanda.itens ?? []).map((item) => (
43	                  <div key={item.id} className="flex items-center justify-between gap-2 bg-[#111111] rounded-lg px-3 py-2">
44	                    <div>
45	                      <p className="text-sm font-bold text-white">{item.quantity}x {item.products?.name}</p>
46	                      {item.observacao && <p className="text-xs text-blue-400">Obs: {item.observacao}</p>}
47	                    </div>
48	                    <span className="text-xs text-[#71717A]">{fmt(item.quantity * item.unit_price)}</span>
49	                  </div>
50	                ))}
51	              </div>
52	              <div className="border-t border-[#2A2A2A] pt-3 flex items-center justify-between">
53	                <span className="text-xs font-bold text-[#71717A] uppercase">Total</span>
54	                <span className="text-lg font-black text-white">{fmt(comanda.total)}</span>
55	              </div>
56	            </>
57	          )}
58	        </div>
59	      </div>
60	    </div>
61	  );
62	};
63	
64	// Linha de produção do Salão — visão unificada de TODOS os setores (cozinha, bar,
65	// salgados...) num painel só, dono acessa direto logado (sem link/token separado, mesmo
66	// padrão de acesso da tela de Cozinha do delivery). Cada setor é uma impressora
67	// cadastrada; itens vêm de order_items roteados pra ela (ver GET /restaurante/kds),
68	// lista PLANA por item (não agrupa por mesa/comanda), com cronômetro de espera/preparo.
69	const RestauranteProducao = () => {
70	  const navigate = useNavigate();
71	  const [impressoras, setImpressoras] = useState(null);
72	  const [itensPorImpressora, setItensPorImpressora] = useState({});
73	  const [restauranteNome, setRestauranteNome] = useState('');
74	  const [loading, setLoading] = useState(true);
75	  const [erro, setErro] = useState(null);
76	  const [lastUpdate, setLastUpdate] = useState(null);
77	  const [comandaAbertaId, setComandaAbertaId] = useState(null);
78	  const now = useNowTick();
79	  const [filtroCanal, setFiltroCanal] = useState('todos'); // 'todos' | 'delivery' | 'salao'
80	  const [verTodosEntregues, setVerTodosEntregues] = useState({}); // { [impressoraId]: bool }
81	  const [busca, setBusca] = useState('');
82	  const prevItemIds = useRef(new Set());
83	  const firstLoad = useRef(true);
84	  const tocarSom = useNotificacaoSonora('cozinha');
85	
86	  useEffect(() => {
87	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
88	    listarImpressoras().then(setImpressoras).catch((e) => setErro(e.message));
89	  }, []);
90	
91	  const carregar = useCallback(async (lista) => {
92	    try {
93	      const resultados = await Promise.all(
94	        lista.map((imp) => getKdsItensRestaurante(imp.id).then((r) => [imp, r.itens ?? []])),
95	      );
96	      const porImpressora = {};
97	      const idsAgora = new Set();
98	      for (const [imp, itens] of resultados) {
99	        porImpressora[imp.id] = itens;
100	        for (const i of itens) idsAgora.add(i.id);
101	      }
102	
103	      if (!firstLoad.current) {
104	        const novos = [...idsAgora].filter((id) => !prevItemIds.current.has(id));
105	        if (novos.length > 0) tocarSom();
106	      } else {
107	        firstLoad.current = false;
108	      }
109	      prevItemIds.current = idsAgora;
110	
111	      setItensPorImpressora(porImpressora);
112	      setLastUpdate(new Date());
113	      setErro(null);
114	    } catch (e) {
115	      setErro(e.message);
116	    } finally {
117	      setLoading(false);
118	    }
119	  }, [tocarSom]);
120	
121	  useEffect(() => {
122	    if (!impressoras) return;
123	    if (impressoras.length === 0) { setLoading(false); return; }
124	    carregar(impressoras);
125	    const interval = setInterval(() => carregar(impressoras), 15000);
126	    return () => clearInterval(interval);
127	  }, [impressoras, carregar]);
128	
129	  const marcarPronto = async (itemId) => {
130	    await marcarItemProntoRestaurante(itemId);
131	    carregar(impressoras);
132	  };
133	
134	  const iniciarPreparo = async (item) => {
135	    await iniciarPreparoItemRestaurante(item.id);
136	    carregar(impressoras);
137	  };
138	
139	  const voltarItem = async (item) => {
140	    await voltarStatusItemRestaurante(item.id);
141	    carregar(impressoras);
142	  };
143	
144	  const moverItem = async (item, direcao) => {
145	    try {
146	      await moverItemRestaurante(item.id, direcao);
147	      carregar(impressoras);
148	    } catch (e) {
149	      alert(e.message);
150	    }
151	  };
152	
153	  const cancelarItem = async (item) => {
154	    if (!confirm(`Cancelar "${item.product_name}"? Esta ação não pode ser desfeita.`)) return;
155	    try {
156	      await cancelarItemRestaurante(item.id);
157	      carregar(impressoras);
158	    } catch (e) {
159	      alert(e.message);
160	    }
161	  };
162	
163	  const reimprimir = async (item, setorNome) => {
164	    try {
165	      const res = await reimprimirItemRestaurante(item.id);
166	      if (res.via === 'navegador') {
167	        printTicketSetor([item], { mesaLabel: item.mesa, cliente_mesa_nome: item.cliente, numero_comanda: item.numero_comanda }, setorNome);
168	      }
169	    } catch (e) {
170	      setErro(e.message);
171	    }
172	  };
173	
174	  const salvarObservacao = async (item, observacao) => {
175	    try {
176	      await editarItemComandaSalao(item.order_id, item.id, { observacao });
177	      carregar(impressoras);
178	    } catch (e) {
179	      setErro(e.message);
180	    }
181	  };
182	
183	  if (loading) return (
184	    <div className="min-h-screen bg-[#111111] flex items-center justify-center">
185	      <div className="w-10 h-10 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
186	    </div>
187	  );
188	
189	  const todosItens = Object.values(itensPorImpressora).flat();
190	  const totalDelivery = todosItens.filter((i) => i.tipo === 'delivery').length;
191	  const totalSalao = todosItens.filter((i) => i.tipo === 'salao').length;
192	  const buscaNormalizada = busca.trim().toLowerCase();
193	  // Leitor de código de barras digita os dígitos zero-padded (ver barcodeValue em
194	  // printComanda.js) e manda Enter — bate exato no numero_comanda, não por substring
195	  // (senão "00000042" nunca acharia a comanda #42).
196	  const numeroComandaEscaneado = /^\d+$/.test(busca.trim()) ? parseInt(busca.trim(), 10) : null;
197	  const passaBusca = (i) => {
198	    if (!buscaNormalizada) return true;
199	    if (numeroComandaEscaneado !== null && i.numero_comanda === numeroComandaEscaneado) return true;
200	    const alvo = [i.cliente, i.mesa, i.mesa_numero, i.numero_comanda, i.garcom]
201	      .filter((v) => v !== null && v !== undefined)
202	      .join(' ')
203	      .toLowerCase();
204	    return alvo.includes(buscaNormalizada);
205	  };
206	  const passaFiltro = (i) => (filtroCanal === 'todos' || i.tipo === filtroCanal) && passaBusca(i);
207	  const totalItens = todosItens.filter(passaFiltro).length;
208	  // Igual à caixa de leitor da Cozinha: verde quando acha a comanda escaneada, vermelho
209	  // quando não acha — só reage ao código exato, busca por nome/mesa/garçom fica neutra.
210	  const itemEncontradoBusca = numeroComandaEscaneado !== null && todosItens.some((i) => i.numero_comanda === numeroComandaEscaneado);
211	  const corBuscaCod = numeroComandaEscaneado === null ? null : itemEncontradoBusca ? 'ok' : 'erro';
212	
213	  return (
214	    <div className="min-h-screen bg-[#111111]">
215	      <header className="bg-[#1A1A1A] border-b border-[#2A2A2A] px-5 py-3">
216	        <div className="flex items-center gap-4">
217	          <button onClick={() => navigate('/restaurante')} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
218	            <Icon name="ArrowLeft" size={18} />
219	          </button>
220	          <div className="flex items-center gap-2">
221	            <div className="w-8 h-8 bg-[#FF441F] rounded-lg flex items-center justify-center flex-shrink-0">
222	              <Icon name="ChefHat" size={16} className="text-white" />
223	            </div>
224	            <div>
225	              <p className="text-white font-black text-base leading-none">Linha de Produção — Salão</p>
226	              <p className="text-[#71717A] text-xs">{restauranteNome}</p>
227	            </div>
228	          </div>
229	          <div className="ml-auto flex items-center gap-2">
230	            <div className="flex items-center gap-2 text-xs text-[#71717A]">
231	              <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
232	              {lastUpdate?.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) ?? '—'}
233	            </div>
234	            <button onClick={() => carregar(impressoras ?? [])} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
235	              <Icon name="RefreshCw" size={16} />
236	            </button>
237	          </div>
238	        </div>
239	
240	        {/* Busca por cliente, mesa, comanda, garçom ou leitor de código de barras — mesma
241	            caixa (cor, botão Buscar, texto de confirmação) da Cozinha */}
242	        <div className={`flex items-center gap-2 mt-3 px-3 py-2 rounded-xl border transition-colors ${
243	          corBuscaCod === 'ok' ? 'border-green-500 bg-green-900/20' :
244	          corBuscaCod === 'erro' ? 'border-red-500 bg-red-900/20' :
245	          'border-[#2A2A2A] bg-[#111111] focus-within:border-[#FF441F]'
246	        }`}>
247	          <Icon name="ScanLine" size={16} className={`flex-shrink-0 ${corBuscaCod === 'ok' ? 'text-green-400' : corBuscaCod === 'erro' ? 'text-red-400' : 'text-[#71717A]'}`} />
248	          <input
249	            type="text"
250	            value={busca}
251	            onChange={(e) => setBusca(e.target.value)}
252	            placeholder="Buscar por cliente, mesa, comanda, garçom ou aponte o leitor..."
253	            className="flex-1 bg-transparent text-white text-sm placeholder:text-[#3A3A3A] outline-none"
254	          />
255	          {busca && (
256	            <>
257	              <button
258	                onClick={() => {
259	                  const alvo = todosItens.find((i) => i.numero_comanda === numeroComandaEscaneado);
260	                  if (alvo) document.getElementById(`salao-item-${alvo.id}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
261	                }}
262	                className="flex-shrink-0 px-3 py-1 bg-[#FF441F] text-white text-xs font-bold rounded-lg hover:bg-[#E63A19]">
263	                Buscar
264	              </button>
265	              <button onClick={() => setBusca('')} className="text-[#71717A] hover:text-white flex-shrink-0">
266	                <Icon name="X" size={15} />
267	              </button>
268	            </>
269	          )}
270	        </div>
271	        {corBuscaCod && (
272	          <p className={`text-xs font-semibold mt-1.5 ${corBuscaCod === 'ok' ? 'text-green-400' : 'text-red-400'}`}>
273	            {corBuscaCod === 'ok' ? `Comanda #${numeroComandaEscaneado} encontrada` : `Comanda #${numeroComandaEscaneado} não encontrada`}
274	          </p>
275	        )}
276	
277	        {/* Filtro de canal — Todos/Delivery/Salão */}
278	        <div className="flex items-center gap-2 mt-3">
279	          {[
280	            { key: 'todos', label: 'Todos', count: totalDelivery + totalSalao },
281	            { key: 'delivery', label: 'Delivery', count: totalDelivery },
282	            { key: 'salao', label: 'Salão', count: totalSalao },
283	          ].map((f) => (
284	            <button
285	              key={f.key}
286	              onClick={() => setFiltroCanal(f.key)}
287	              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${
288	                filtroCanal === f.key
289	                  ? 'bg-[#FF441F] text-white'
290	                  : 'bg-[#111111] text-[#71717A] border border-[#2A2A2A] hover:text-white'
291	              }`}
292	            >
293	              {f.label}
294	              <span className={`px-1.5 py-0.5 rounded-full text-[10px] ${filtroCanal === f.key ? 'bg-white/20' : 'bg-[#2A2A2A]'}`}>{f.count}</span>
295	            </button>
296	          ))}
297	        </div>
298	      </header>
299	
300	      {erro && (
301	        <div className="mx-5 mt-4 bg-red-900/50 border border-red-700 rounded-xl px-4 py-3 text-sm text-red-400">{erro}</div>
302	      )}
303	
304	      {impressoras && impressoras.length === 0 ? (
305	        <div className="text-center py-20 px-5">
306	          <Icon name="Printer" size={48} className="text-[#2A2A2A] mx-auto mb-4" />
307	          <p className="text-[#71717A] text-lg font-semibold">Nenhuma impressora cadastrada</p>
308	          <p className="text-[#3A3A3A] text-sm mt-1">Cada setor (Cozinha, Bar, Salgados...) precisa de uma impressora cadastrada com esse setor.</p>
309	          <button onClick={() => navigate('/restaurante/impressoras')}
310	            className="mt-4 px-4 py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl hover:bg-[#E63A19]">
311	            Ir pra Impressoras
312	          </button>
313	        </div>
314	      ) : (
315	        <main className="p-5 max-w-6xl mx-auto space-y-8">
316	          {(impressoras ?? []).map((imp) => {
317	            const itens = (itensPorImpressora[imp.id] ?? []).filter(passaFiltro);
318	            const aguardando = itens.filter((i) => i.status === 'enviado');
319	            const preparando = itens.filter((i) => i.status === 'preparando');
320	            const entregues = itens
321	              .filter((i) => i.status === 'pronto')
322	              .sort((a, b) => new Date(b.pronto_em).getTime() - new Date(a.pronto_em).getTime());
323	            return (
324	              <div key={imp.id}>
325	                <div className="flex items-center gap-2 mb-3">
326	                  <div className="w-2.5 h-2.5 rounded-full bg-orange-400" />
327	                  <h2 className="text-white font-bold text-sm uppercase tracking-wider">{imp.setor}</h2>
328	                  {itens.length > 0 && (
329	                    <span className="bg-orange-500 text-white text-xs font-black px-2 py-0.5 rounded-full">
330	                      {itens.length}
331	                    </span>
332	                  )}
333	                </div>
334	                {itens.length === 0 ? (
335	                  <div className="rounded-2xl border-2 border-dashed border-[#2A2A2A] p-6 text-center mb-2">
336	                    <p className="text-[#71717A] text-sm">Nenhum item pendente em {imp.setor}</p>
337	                  </div>
338	                ) : (
339	                  <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
340	                    <div>
341	                      <p className="text-xs font-bold text-blue-400 uppercase tracking-wider mb-2">Aguardando Preparo</p>
342	                      {aguardando.length === 0 ? (
343	                        <p className="text-xs text-[#71717A]">Nenhum</p>
344	                      ) : (
345	                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-3">
346	                          {aguardando.map((item, idx) => (
347	                            <SalaoItemCard key={item.id} item={item} posicao={idx + 1} now={now}
348	                              ehPrimeiro={idx === 0} ehUltimo={idx === aguardando.length - 1} onMover={moverItem}
349	                              onReimprimir={(it) => reimprimir(it, imp.setor)} onIniciarPreparo={iniciarPreparo} onMarcarPronto={marcarPronto} onVoltar={voltarItem} onCancelar={cancelarItem} onAbrirComanda={setComandaAbertaId} onSalvarObservacao={salvarObservacao}
350	                              highlighted={numeroComandaEscaneado !== null && item.numero_comanda === numeroComandaEscaneado} />
351	                          ))}
352	                        </div>
353	                      )}
354	                    </div>
355	                    <div>
356	                      <p className="text-xs font-bold text-orange-400 uppercase tracking-wider mb-2">Em Preparo</p>
357	                      {preparando.length === 0 ? (
358	                        <p className="text-xs text-[#71717A]">Nenhum</p>
359	                      ) : (
360	                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-3">
361	                          {preparando.map((item, idx) => (
362	                            <SalaoItemCard key={item.id} item={item} posicao={idx + 1} now={now}
363	                              onReimprimir={(it) => reimprimir(it, imp.setor)} onIniciarPreparo={iniciarPreparo} onMarcarPronto={marcarPronto} onVoltar={voltarItem} onAbrirComanda={setComandaAbertaId} onSalvarObservacao={salvarObservacao}
364	                              highlighted={numeroComandaEscaneado !== null && item.numero_comanda === numeroComandaEscaneado} />
365	                          ))}
366	                        </div>
367	                      )}
368	                    </div>
369	                    <div>
370	                      <p className="text-xs font-bold text-emerald-400 uppercase tracking-wider mb-2">Entregues hoje</p>
371	                      {entregues.length === 0 ? (
372	                        <p className="text-xs text-[#71717A]">Nenhum</p>
373	                      ) : (
374	                        <>
375	                          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-3">
376	                            {(verTodosEntregues[imp.id] ? entregues : entregues.slice(0, 2)).map((item, idx) => (
377	                              <SalaoItemCard key={item.id} item={item} posicao={idx + 1} now={now}
378	                                onReimprimir={(it) => reimprimir(it, imp.setor)} onIniciarPreparo={iniciarPreparo} onMarcarPronto={marcarPronto} onVoltar={voltarItem} onAbrirComanda={setComandaAbertaId} onSalvarObservacao={salvarObservacao}
379	                                highlighted={numeroComandaEscaneado !== null && item.numero_comanda === numeroComandaEscaneado} />
380	                            ))}
381	                          </div>
382	                          {entregues.length > 2 && (
383	                            <button onClick={() => setVerTodosEntregues((v) => ({ ...v, [imp.id]: !v[imp.id] }))}
384	                              className="mt-3 w-full py-2 text-xs font-bold text-emerald-400 border border-emerald-500/30 rounded-xl hover:bg-emerald-500/10">
385	                              {verTodosEntregues[imp.id] ? 'Recolher / fechar a lista' : `Ver todos (${entregues.length})`}
386	                            </button>
387	                          )}
388	                        </>
389	                      )}
390	                    </div>
391	                  </div>
392	                )}
393	              </div>
394	            );
395	          })}
396	          {totalItens === 0 && (
397	            <div className="text-center py-16">
398	              <Icon name="UtensilsCrossed" size={48} className="text-[#2A2A2A] mx-auto mb-4" />
399	              <p className="text-[#71717A] text-lg font-semibold">Tudo tranquilo</p>
400	              <p className="text-[#3A3A3A] text-sm mt-1">Nenhum item pendente em nenhum setor agora</p>
401	            </div>
402	          )}
403	        </main>
404	      )}
405	
