1	import React, { useState, useEffect, useCallback, useRef } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import {
4	  getPedidosCozinha, atualizarStatusPedido, getMinhaEmpresa, renovarTokenCozinha,
5	  listarImpressoras, getKdsItensRestaurante, marcarItemProntoRestaurante, iniciarPreparoItemRestaurante, voltarStatusItemRestaurante,
6	} from '../../services/restauranteService';
7	import {
8	  getCozinhaToken, setCozinhaToken, clearCozinhaToken, resgatarToken,
9	  getCozinhaMe, getCozinhaPedidos, atualizarStatusCozinhaPortal,
10	  getKdsImpressoras, getKdsItens, marcarItemPronto, iniciarPreparoItem, voltarStatusItem,
11	} from '../../services/cozinhaPortalService';
12	import { supabase } from '../../lib/supabase';
13	import Icon from '../../components/AppIcon';
14	import SalaoItemCard from '../../components/restaurante/SalaoItemCard';
15	import { barcodeValue, getPrinterName, setPrinterName } from '../../utils/printComanda';
16	import { formatDuracao } from '../../utils/formatDuracao';
17	import { useNotificacaoSonora } from '../../hooks/useNotificacaoSonora';
18	import { useNowTick } from '../../hooks/useNowTick';
19	
20	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
21	const PAYMENT_LABELS = { pix: 'PIX', credit_card: 'Cartão', debit_card: 'Débito', cash: 'Dinheiro' };
22	
