1	import React, { useState, useEffect } from 'react';
2	import Icon from '../AppIcon';
3	import { formatDuracao } from '../../utils/formatDuracao';
4	
5	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
6	const PAYMENT_LABELS = { pix: 'PIX', credit_card: 'Cartão', debit_card: 'Débito', cash: 'Dinheiro' };
7	
8	// Alerta de motoboy (só item de delivery, com pedido já despachado) — pisca amarelo em
9	// trânsito, verde quando entregou, vermelho se o motoboy registrou ocorrência. Dados vêm
10	// do pedido (orders.status/motoboy_lat/lng/delivery_occurrence) via getKdsSetor.
11	const AlertaMotoboy = ({ item }) => {
12	  const temOcorrencia = item.delivery_occurrence === 'pendente';
13	  const entregue = item.pedido_status === 'delivered';
14	  const emTransito = item.pedido_status === 'out_for_delivery' || item.pedido_status === 'motoboy_collecting';
15	  const temMapa = item.motoboy_lat != null && item.motoboy_lng != null;
16	
17	  if (!temOcorrencia && !entregue && !emTransito && !temMapa) return null;
18	
19	  const cor = temOcorrencia ? 'bg-red-500' : entregue ? 'bg-emerald-500' : emTransito ? 'bg-yellow-400' : null;
20	  const label = temOcorrencia ? 'Ocorrência do motoboy' : entregue ? 'Entregue' : emTransito ? 'Motoboy em trânsito' : '';
21	
22	  return (
23	    <div className="flex items-center gap-1.5 flex-shrink-0">
24	      {cor && <span className={`w-2.5 h-2.5 rounded-full ${cor} animate-pulse`} title={label} />}
25	      {temMapa && (
26	        <a href={`https://www.google.com/maps?q=${item.motoboy_lat},${item.motoboy_lng}`} target="_blank" rel="noopener noreferrer"
27	          className="p-1 text-[#71717A] hover:text-[#18181B] dark:hover:text-white rounded-md hover:bg-[#F4F4F5] dark:hover:bg-[#2A2A2A]" title="Localizar motoboy no mapa">
28	          <Icon name="MapPin" size={13} />
29	        </a>
30	      )}
31	    </div>
32	  );
33	};
34	
35	// Card de item por praça de preparo (Cozinha unificada/Bar/Produção/pontos de preparo
36	// customizáveis) — mesmo componente em TODAS as telas, pra nunca mais divergir estilo
37	// nem rótulo entre elas. Item de delivery usa o mesmo visual claro da Cozinha (fácil de
38	// bater o olho e identificar); item de salão mantém o tema escuro já usado. Ação é
39	// sempre por ITEM (não pelo pedido inteiro) — cada praça só controla o que é dela; o
40	// pedido de delivery só vira "pronto" pro motoboy quando todas as praças envolvidas
41	// já marcaram seus itens (ver marcarItemPronto no backend).
42	const SalaoItemCard = ({
43	  item, posicao, now, onReimprimir, onIniciarPreparo, onMarcarPronto, onVoltar, onCancelar,
44	  onMover, ehPrimeiro, ehUltimo, onAbrirComanda, onSalvarObservacao, highlighted = false,
45	}) => {
46	  const enviadoEm = new Date(item.enviado_em).getTime();
47	  const preparandoEm = item.preparando_em ? new Date(item.preparando_em).getTime() : null;
48	  const tempoEspera = (preparandoEm ?? now) - enviadoEm;
49	  const tempoPreparo = preparandoEm ? now - preparandoEm : 0;
50	  const tempoTotal = now - enviadoEm;
51	  const ehDelivery = item.tipo === 'delivery';
52	  const podeAbrirComanda = !ehDelivery && !!item.numero_comanda && !!onAbrirComanda;
53	  const podeEditarObs = !ehDelivery && !!onSalvarObservacao;
54	
55	  const [editandoObs, setEditandoObs] = useState(false);
56	  const [obsInput, setObsInput] = useState(item.observacao ?? '');
57	  useEffect(() => { if (!editandoObs) setObsInput(item.observacao ?? ''); }, [item.observacao, editandoObs]);
58	  const salvarObs = () => { onSalvarObservacao(item, obsInput); setEditandoObs(false); };
59	
60	  const acoes = (
61	    <div className="flex gap-2" onClick={(e) => e.stopPropagation()}>
62	      {item.status !== 'enviado' && (
63	        <button onClick={() => onVoltar(item)} title="Desfazer — clicou errado"
64	          className={`flex-shrink-0 px-3 py-2 text-xs font-bold rounded-xl flex items-center justify-center gap-1.5 ${ehDelivery ? 'bg-[#F4F4F5] dark:bg-[#3F3F46] hover:bg-[#E4E4E7] dark:hover:bg-[#2A2A2A] text-[#71717A] dark:text-[#A1A1AA]' : 'bg-purple-900/40 hover:bg-purple-900/60 text-white'}`}>
65	          <Icon name="Undo2" size={13} /> Voltar
66	        </button>
67	      )}
68	      {item.status === 'enviado' ? (
69	        <>
70	          {onCancelar && (
71	            <button onClick={() => onCancelar(item)} title="Cancelar item"
72	              className={`flex-shrink-0 px-3 py-2 text-xs font-bold rounded-xl flex items-center justify-center gap-1.5 ${ehDelivery ? 'bg-red-50 dark:bg-red-950/40 hover:bg-red-100 dark:hover:bg-red-950/60 text-red-600 dark:text-red-400' : 'bg-red-900/40 hover:bg-red-900/60 text-red-400'}`}>
73	              <Icon name="X" size={13} /> Cancelar
74	            </button>
75	          )}
76	          <button onClick={() => onIniciarPreparo(item)}
77	            className="flex-1 py-2 bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
78	            <Icon name="ChefHat" size={13} /> Iniciar Preparo
79	          </button>
80	        </>
81	      ) : item.status === 'pronto' ? (
82	        <div className={`flex-1 py-2 text-xs font-bold rounded-xl flex items-center justify-center gap-1.5 ${ehDelivery ? 'bg-emerald-50 dark:bg-emerald-950/40 text-emerald-700 dark:text-emerald-400' : 'bg-emerald-900/40 text-emerald-400'}`}>
83	          <Icon name="Check" size={13} /> {item.entregue_garcom ? 'Entregue pelo garçom' : 'Pronto'}
84	        </div>
85	      ) : (
86	        <button onClick={() => onMarcarPronto(item.id)}
87	          className="flex-1 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
88	          <Icon name="Check" size={13} /> Pronto
89	        </button>
90	      )}
91	    </div>
92	  );
93	
94	  const localLabel = ehDelivery
95	    ? (item.cliente ? `Pedido #${item.order_id} • ${item.cliente}` : `Pedido #${item.order_id}`)
96	    : (item.mesa && item.cliente ? `${item.mesa} • ${item.cliente}` : item.mesa ?? item.cliente ?? 'Avulsa');
97	
98	  return (
99	    <div
100	      id={`salao-item-${item.id}`}
101	      onClick={podeAbrirComanda ? () => onAbrirComanda(item.order_id) : undefined}
102	      title={podeAbrirComanda ? 'Ver comanda completa' : undefined}
103	      className={`rounded-2xl border-2 overflow-hidden transition-all duration-300 ${podeAbrirComanda ? 'cursor-pointer' : ''} ${
104	        ehDelivery
105	          ? `bg-white dark:bg-[#27272A] ${podeAbrirComanda ? 'hover:border-[#FF441F]/60' : ''} ${
106	              highlighted ? 'border-yellow-400 ring-2 ring-yellow-400/60 shadow-xl shadow-yellow-300/40 scale-[1.02]'
107	                : item.garcom_nao_entregou ? 'border-red-500 ring-1 ring-red-500/40'
108	                : posicao === 1 ? 'border-yellow-400 ring-1 ring-yellow-400/30'
109	                : 'border-[#E4E4E7] dark:border-[#3F3F46]'
110	            }`
111	          : `bg-purple-950/20 ${
112	              highlighted ? 'border-yellow-400 ring-2 ring-yellow-400/60 shadow-xl shadow-yellow-300/20 scale-[1.02]'
113	                : item.garcom_nao_entregou ? 'border-red-500 ring-1 ring-red-500/40'
114	                : posicao === 1 ? 'border-yellow-400/70 ring-1 ring-yellow-400/30'
115	                : 'border-purple-300'
116	            }`
117	      }`}>
118	      {item.garcom && (
119	        <div className="bg-white px-4 py-2">
120	          <p className="text-center text-lg font-black text-[#18181B] uppercase tracking-wide">{item.garcom}</p>
121	        </div>
122	      )}
123	      <div className="p-4">
124	        <div className="flex items-start justify-between mb-1 gap-2">
125	          <div className="flex items-start gap-2">
126	            <span className={`w-6 h-6 flex-shrink-0 rounded-lg flex items-center justify-center text-xs font-black mt-0.5 ${
127	              posicao === 1 ? 'bg-yellow-400 text-black' : ehDelivery ? 'bg-[#F4F4F5] dark:bg-[#3F3F46] text-[#18181B] dark:text-white' : 'bg-purple-900/50 text-white'
128	            }`}>
129	              {posicao}
130	            </span>
131	            {item.status === 'enviado' && onMover && (
132	              <div className="flex flex-col gap-0.5" onClick={(e) => e.stopPropagation()}>
133	                <button onClick={() => onMover(item, 'cima')} disabled={ehPrimeiro} title="Adiantar — subir na fila"
134	                  className={`w-5 h-4 flex items-center justify-center rounded disabled:opacity-20 ${ehDelivery ? 'text-[#A1A1AA] enabled:hover:text-[#18181B] dark:enabled:hover:text-white enabled:hover:bg-[#F4F4F5] dark:enabled:hover:bg-[#2A2A2A]' : 'text-[#71717A] enabled:hover:text-white enabled:hover:bg-[#2A2A2A]'}`}>
135	                  <Icon name="ChevronUp" size={13} />
136	                </button>
137	                <button onClick={() => onMover(item, 'baixo')} disabled={ehUltimo} title="Atrasar — descer na fila"
138	                  className={`w-5 h-4 flex items-center justify-center rounded disabled:opacity-20 ${ehDelivery ? 'text-[#A1A1AA] enabled:hover:text-[#18181B] dark:enabled:hover:text-white enabled:hover:bg-[#F4F4F5] dark:enabled:hover:bg-[#2A2A2A]' : 'text-[#71717A] enabled:hover:text-white enabled:hover:bg-[#2A2A2A]'}`}>
139	                  <Icon name="ChevronDown" size={13} />
140	                </button>
141	              </div>
142	            )}
143	            <div className="leading-tight">
144	              <p className={`text-xl font-black ${ehDelivery ? 'text-[#18181B] dark:text-[#F4F4F5]' : 'text-white'}`}>Quantidade: {item.quantity}</p>
145	              <p className={`text-lg font-bold ${ehDelivery ? 'text-[#18181B] dark:text-[#F4F4F5]' : 'text-white'}`}>
146	                Produto: {item.product_name}
147	                {!ehDelivery && <span className="text-purple-300 font-normal text-xs"> · Salão</span>}
148	              </p>
149	            </div>
150	          </div>
151	          <div className="flex items-center gap-1.5 flex-shrink-0">
152	            {ehDelivery && <AlertaMotoboy item={item} />}
153	            {onReimprimir && (
154	              <button onClick={(e) => { e.stopPropagation(); onReimprimir(item); }}
155	                className="text-[10px] font-bold text-orange-500 dark:text-orange-400 border border-orange-300 dark:border-orange-500/40 rounded-lg px-2 py-1 hover:bg-orange-50 dark:hover:bg-orange-500/10 flex items-center gap-1 flex-shrink-0">
156	                <Icon name="Printer" size={11} /> Reimpressão
157	              </button>
158	            )}
159	          </div>
160	        </div>
161	
162	        {posicao === 1 && (
163	          <p className={`text-[10px] font-bold uppercase tracking-wide mb-1 ${ehDelivery ? 'text-orange-600 dark:text-yellow-400' : 'text-yellow-400'}`}>Próximo da fila</p>
164	        )}
165	        {item.garcom_nao_entregou && (
166	          <p className="text-sm font-bold text-white bg-red-600 rounded px-1.5 py-0.5 mb-1 animate-pulse">
167	            Esse pedido não foi entregue — garçom não entregou
168	          </p>
169	        )}
170	        {item.is_auto_atendimento && (
171	          <p className="text-sm font-bold text-white bg-pink-600 rounded px-1.5 py-0.5 mb-1">
172	            Auto Atendimento — Mesa {item.mesa_numero ?? '?'}
173	          </p>
174	        )}
175	        {item.garcom_indo_buscar && (
176	          <p className={`text-sm font-bold text-white rounded px-1.5 py-0.5 mb-1 ${item.entregue_garcom ? 'bg-emerald-600' : 'bg-blue-600'}`}>
177	            {item.entregue_garcom ? 'Já entregue pelo garçom' : 'Garçom vindo buscar'}
178	          </p>
179	        )}
180	
181	        {editandoObs ? (
182	          <div className="flex items-center gap-1.5 mb-1" onClick={(e) => e.stopPropagation()}>
183	            <input value={obsInput} onChange={(e) => setObsInput(e.target.value)} autoFocus
184	              placeholder="Observação..."
185	              className="flex-1 text-xs bg-[#F4F4F5] dark:bg-[#111111] border border-[#E4E4E7] dark:border-[#3A3A3A] rounded-lg px-2 py-1 text-[#18181B] dark:text-white focus:outline-none focus:border-[#FF441F]" />
186	            <button onClick={salvarObs} className="text-xs font-bold text-emerald-600 dark:text-emerald-400">Salvar</button>
187	            <button onClick={() => setEditandoObs(false)} className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Cancelar</button>
188	          </div>
189	        ) : item.observacao ? (
190	          <p onClick={podeEditarObs ? (e) => { e.stopPropagation(); setEditandoObs(true); } : undefined}
191	            className={`text-sm font-bold text-white bg-blue-600 rounded px-1.5 py-0.5 mb-1 animate-pulse ${podeEditarObs ? 'cursor-pointer' : ''}`}>
192	            Obs: {item.observacao}
193	          </p>
194	        ) : podeEditarObs ? (
195	          <button onClick={(e) => { e.stopPropagation(); setEditandoObs(true); }}
196	            className="flex items-center gap-1 mb-1 text-xs text-[#71717A] dark:text-[#A1A1AA] hover:text-[#18181B] dark:hover:text-white">
197	            <Icon name="MessageSquare" size={11} /> Adicionar observação
198	          </button>
199	        ) : null}
200	
201	        <div className={`flex items-center gap-2 text-base font-bold mb-2 ${ehDelivery ? 'text-[#FF441F]' : 'text-yellow-400'}`}>
202	          <Icon name="MapPin" size={14} />
203	          <span className={ehDelivery ? 'text-sm' : ''}>{localLabel}</span>
204	          {item.numero_comanda && (
205	            <>
206	              <span className={ehDelivery ? 'text-[#A1A1AA]' : 'text-[#71717A]'}>•</span>
207	              <span>Comanda #{item.numero_comanda}</span>
208	            </>
209	          )}
210	          <span className={`ml-auto px-1.5 py-0.5 rounded-full text-[10px] font-bold ${ehDelivery ? 'bg-sky-100 dark:bg-sky-500/20 text-sky-700 dark:text-sky-400' : 'bg-purple-500/20 text-purple-300'}`}>
211	            {ehDelivery ? 'Delivery' : 'Salão'}
212	          </span>
213	        </div>
214	
215	        {ehDelivery && (item.pedido_total != null || item.pedido_payment_method) && (
216	          <div className="flex items-center justify-between mb-2 pb-2 border-b border-[#F4F4F5] dark:border-[#3F3F46] text-xs">
217	            <span className="text-[#71717A] dark:text-[#A1A1AA]">{PAYMENT_LABELS[item.pedido_payment_method] ?? item.pedido_payment_method}</span>
218	            {item.pedido_total != null && <span className="font-black text-[#FF441F]">{fmt(item.pedido_total)}</span>}
219	          </div>
220	        )}
221	
222	        <div className={`flex items-center gap-3 text-[11px] font-mono mb-3 ${ehDelivery ? 'text-[#71717A] dark:text-[#A1A1AA]' : ''}`}>
223	          <span className="flex items-center gap-1 text-blue-600 dark:text-blue-400">
224	            <Icon name="Clock" size={11} /> espera {formatDuracao(tempoEspera)}
225	          </span>
226	          {item.status === 'preparando' && (
227	            <span className="flex items-center gap-1 text-orange-600 dark:text-orange-400">
228	              <Icon name="Flame" size={11} /> preparo {formatDuracao(tempoPreparo)}
229	            </span>
230	          )}
231	          <span className={`ml-auto ${ehDelivery ? 'text-[#A1A1AA]' : 'text-[#71717A]'}`}>total {formatDuracao(tempoTotal)}</span>
232	        </div>
233	
234	        {acoes}
235	      </div>
236	    </div>
237	  );
238	};
239	
240	export default SalaoItemCard;
